create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.admin_roles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check (role in ('admin','moderator')), created_at timestamptz not null default now());
create or replace function public.is_shaxai_admin() returns boolean language sql stable security definer set search_path = '' as $$ select exists(select 1 from public.admin_roles where user_id=(select auth.uid())); $$;
create table public.conversations (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null default 'Yangi suhbat', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('user','assistant','system')), content text not null, created_at timestamptz not null default now());
create table public.knowledge_entries (id uuid primary key default gen_random_uuid(), author_id uuid not null references auth.users(id) on delete cascade, title text not null check(char_length(title) between 3 and 180), content text not null check(char_length(content) between 10 and 12000), source_url text, status text not null default 'pending' check(status in ('pending','approved','rejected')), review_note text, reviewed_by uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index conversations_user_updated_idx on public.conversations(user_id,updated_at desc);
create index messages_conversation_created_idx on public.messages(conversation_id,created_at);
create index knowledge_status_created_idx on public.knowledge_entries(status,created_at desc);
create index knowledge_author_created_idx on public.knowledge_entries(author_id,created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at=now(); return new; end; $$;
create or replace function public.handle_new_shaxai_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'full_name',''),nullif(new.raw_user_meta_data->>'name',''),split_part(coalesce(new.email,'Foydalanuvchi'),'@',1))) on conflict(id) do nothing; return new; end; $$;
create trigger on_shaxai_auth_user_created after insert on auth.users for each row execute function public.handle_new_shaxai_user();
create trigger profiles_set_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger conversations_set_updated_at before update on public.conversations for each row execute function public.set_updated_at();
create trigger knowledge_set_updated_at before update on public.knowledge_entries for each row execute function public.set_updated_at();
alter table public.profiles enable row level security;
alter table public.admin_roles enable row level security;
alter table public.conversations enable row level security;
alter table public.messages enable row level security;
alter table public.knowledge_entries enable row level security;
grant select,insert,update on public.profiles to authenticated;
grant select,insert,update,delete on public.admin_roles to authenticated;
grant select,insert,update,delete on public.conversations to authenticated;
grant select,insert on public.messages to authenticated;
grant select,insert,update on public.knowledge_entries to authenticated;
grant select on public.knowledge_entries to anon;
create policy "Users read own profile" on public.profiles for select to authenticated using((select auth.uid())=id);
create policy "Users update own profile" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy "Users manage own conversations" on public.conversations for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
create policy "Users read messages in own conversations" on public.messages for select to authenticated using(exists(select 1 from public.conversations c where c.id=conversation_id and c.user_id=(select auth.uid())));
create policy "Users add messages to own conversations" on public.messages for insert to authenticated with check(user_id=(select auth.uid()) and exists(select 1 from public.conversations c where c.id=conversation_id and c.user_id=(select auth.uid())));
create policy "Users submit knowledge for review" on public.knowledge_entries for insert to authenticated with check(author_id=(select auth.uid()) and status='pending');
revoke all on function public.handle_new_shaxai_user() from public,anon,authenticated;
revoke all on function public.is_shaxai_admin() from public,anon;
grant execute on function public.is_shaxai_admin() to authenticated;
